import psutil

def check_hollowing(pid):
    process = psutil.Process(pid)
    for section in process.memory_maps():
        # Look for memory that is both Writable and Executable
        # This is a huge red flag for injected or hollowed code
        if "rwx" in section.path.lower():
            print(f"[!] Suspicious RWX section found in PID {pid}: {section.addr}")

# Scan all running processes
for proc in psutil.process_iter(['pid']):
    check_hollowing(proc.info['pid'])
